package tn.smartuniversity.user;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document;
@Document("users") public class AppUser { @Id private String id; private String firstName; private String lastName; @Indexed(unique=true) private String email; private String password; private String role; private String studentId; private String employeeId; private String department; private String specialty; private boolean enabled=true; public String getId(){return id;} public void setId(String v){id=v;} public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public String getStudentId(){return studentId;} public void setStudentId(String v){studentId=v;} public String getEmployeeId(){return employeeId;} public void setEmployeeId(String v){employeeId=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getSpecialty(){return specialty;} public void setSpecialty(String v){specialty=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} }
